package org.example.filters;

import org.mule.api.filter.Filter;
import org.mule.api.filter.FilterException;
import org.mule.module.sftp.SftpConnector;

public class SftpTimeoutFilter implements Filter {

    private long timeout = 30000; // 30 seconds by default

    @Override
    public boolean filter(MuleEventContext event) throws FilterException {
        try {
            SftpConnector connector = (SftpConnector) event.getMessage().getOutboundProperty("sftp.connector");
            if (connector != null && !connector.isConnected()) {
                // Wait for the connection to establish or timeout
                long start = System.currentTimeMillis();
                while (!connector.isConnected() && System.currentTimeMillis() - start < timeout) {
                    Thread.sleep(1000); // wait 1 second at a time
                }
                if (System.currentTimeMillis() - start >= timeout) {
                    throw new FilterException("SFTP connection timed out after " + timeout + " milliseconds");
                }
            }
        } catch (Exception e) {
            throw new FilterException(e);
        }
        return true;
    }

    public void setTimeout(long timeout) {
        this.timeout = timeout;
    }
}
