private static final long RATE_LIMIT_DURATION = 60 * 1000; // 1 minute in milliseconds

public class RateLimitingSourceTransformer implements Transformer {

    private Map<String, Long> sendingFacilityRates;
    private List<Long> rateCheckQueue;

    @Override
