                rateCheckQueue = new ArrayList<>();
            }
            Long lastRateCheck = sendingFacilityRates.get(sendingFacility);
            long now = System.currentTimeMillis();
            if (now - lastRateCheck > RATE_LIMIT_DURATION) {
                // Update the rate tracking map
                sendingFacilityRates.put(sendingFacility, now);
                return false; // Not rate limited yet
            }
        }
