```java
import com.mirth.connectors.http.HttpMessageDispatcher;
import com.mirth.connectors.http.HttpRequest;
import com.mirth.connectors.http.HttpResponse;

public class RateLimiter {
    private static final int RATE_LIMIT = 5000; // 5,000 messages per minute

    public HttpResponse process(HttpRequest request) throws Exception {
        // Get the sending facility ID from the message
        String sendingFacilityId = getSendingFacilityId(request);

        // Check if we've exceeded our rate limit for this facility
        long lastUpdateTime = getLastUpdateTime(sendingFacilityId);
        if (lastUpdateTime != -1 && System.currentTimeMillis() - lastUpdateTime < RATE_LIMIT * 60 * 1000) {
            // Rate limit exceeded, return an error response
            HttpResponse response = new HttpResponse();
            response.setStatus(HttpResponse.STATUS_CODE_429_TOO_MANY_REQUESTS);
            response.setReasonPhrase("Rate limit exceeded");
            return response;
        }

        // Update the last update time for this facility
        setLastUpdateTime(sendingFacilityId, System.currentTimeMillis());

        // Process the message as usual
        HttpMessageDispatcher dispatcher = new HttpMessageDispatcher();
        HttpResponse response = dispatcher.dispatch(request);

        return response;
    }
}
```

