// Define constants for rate limiting
private static final int RATE_LIMIT = 5000; // messages per minute

public class RateLimitingSourceTransformer implements Transformer {

    private Map<String, Long> sendingFacilityCache = new HashMap<>();

    @Override
    public Object transform(Object message) {
        String sendingFacility = (String) message.get("sending_facility");

        if (!sendingFacilityCache.containsKey(sendingFacility)) {
            // Initialize the cache for this sending facility
            sendingFacilityCache.put(sendingFacility, System.currentTimeMillis());
        }

        Long lastSendTime = sendingFacilityCache.get(sendingFacility);
        long currentTime = System.currentTimeMillis();

        int timeDiff = (int) ((currentTime - lastSendTime) / 1000); // convert to seconds

        if (timeDiff > RATE_LIMIT * 60) { // check rate limit
            // Sleep for the remaining time to respect the rate limit
            Thread.sleep((RATE_LIMIT * 60 - timeDiff) * 1000);
        }

        sendingFacilityCache.put(sendingFacility, currentTime);

        return message;
    }
}
```
