    const requestCache = {};
    let retryInterval = 500; // 0.5 seconds

    return function transform(message, properties) {
        if (!message.getDestination()) return message;

        // Cache the incoming request
        const requestId = message.getMessageId();
        requestCache[requestId] = {
            timestamp: new Date(),
            payload: message.getPayload()
        };

        // Set a timer to re-send the cached requests after `retryInterval` milliseconds
        setTimeout(() => {
            if (Object.keys(requestCache).length > 0) {
                const now = new Date();
                for (const requestId in requestCache) {
                    const cachedRequest = requestCache[requestId];
                    if ((now.getTime() - cachedRequest.timestamp.getTime()) >= retryInterval) {
                        // Re-send the cached request
                        message.setPayload(cachedRequest.payload);
                        ctx.send(message, properties);
                        delete requestCache[requestId]; // Remove from cache after successful send
                    }
                }
            }
        }, retryInterval);

        return message;
    };
};
```
