// Import necessary libraries
import java.util.regex.Matcher;
import java.util.regex.Pattern;

// Define the transformer class
public class StripPHITransformer implements Transformer {

    // Regular expression pattern to match PHI in HL7 messages
    private static final Pattern PHI_PATTERN = Pattern.compile("([A-Z]{3}[0-9]{1,2})([0-9]{8})");

