import org.apache.commons.net.SocketTimeout;
import org.mule.api.MuleMessage;
import org.mule.module.http.client.HttpClientException;

public class SoapConnectionTimeoutHandler implements org.mule.module.http.filter.Filter {

    private static final int DEFAULT_TIMEOUT = 30; // seconds

    @Override
    public void filter(MuleMessage message) {
