            }
        } catch (Exception e) {
            // Log the error and continue processing the message
            logger.error("Error setting connection timeout: " + e.getMessage());
        }
    }

    @Override
    public boolean supports(org.mule.api.MuleMessage message) {
        return true; // This filter is applicable to all Mule messages that involve SOAP requests.
    }
}
