public class SftpTimeoutHandler implements Transformer {

    @Override
    public Bundle transform(Bundle bundle) {
        // Get the SFTP client from the message context
        SFTPClient sftp = (SFTPClient) bundle.getMessageContext().get("sftp");

        try {
            // Connect to the SFTP server with a timeout of 30 seconds
            sftp.connect(30000);

            // Process the file transfer as usual
            bundle.process();

        } catch (Exception e) {
            // Handle connection timeout errors
            if (e instanceof java.net.SocketTimeoutException || e instanceof org.apache.commons.net.sftp.SftpException) {
                // Log an error and return a failed message
                log.error("SFTP connection timed out: " + sftp.getHostName());
                bundle.setFailed(true);
            }
        } finally {
            // Close the SFTP client to release resources
            if (sftp != null) {
                sftp.disconnect();
            }
        }

        return bundle;
    }
}
