interface MessageBuilder<T extends keyof HL7v2Segments> {
  segments: Record<T, Segment>;

  addSegment(type: T, ...fields): void;
  build(): string;
}

const hl7v2Segments = {
  MSH: { type: 'MSH' },
  PID: { type: 'PID' },
  PV1: { type: 'PV1' },
  // Add more segments as needed
} as Record<string, { type: string }>;

export class HL7v2MDMMessageBuilder implements MessageBuilder<keyof hl7v2Segments> {
  segments = {} as Record<keyof hl7v2Segments, Segment>;

  addSegment(type: keyof hl7v2Segments, ...fields): void {
    this.segments[type] = { type, fields };
  }

  build(): string {
    let message = '';
    for (const [type, segment] of Object.entries(this.segments)) {
      message += `${segment.type}~';
      for (const field in segment.fields) {
        if (field !== 'type') {
          message += `${field}=${segment.fields[field]}~`;
        }
      }
      message += '\r\n';
    }
    return message;
  }
}
```
