            }
            else if (chars[i] == '\r' && chars[i + 1] == '\n')
            {
                // Replace `\r\n` with a newline character
                parsedMessage.Append('\n');
                i += 2; // Skip the next two characters, which are '\r' and '\n'
            }

            parsedMessage.Append(chars[i]);
