import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Hl7Parser {
    public static String parseHl7Message(String hl7Message) throws Exception {
        // Define the pattern for HL7 escape sequences
        Pattern escapePattern = Pattern.compile("\\x(0[0-9A-F]{1,2})");

        Matcher matcher = escapePattern.matcher(hl7Message);

        while (matcher.find()) {
