Here's the step-by-step implementation:

**Step 1: Define the conversion function**
```javascript
function convertDiagnosticReportToFV1(dicomReport) {
  // Initialize an empty HL7 v2 PV1 message
  const pv1Message = new hl7v2.Message('PV1');

  // Set the required fields for the PV1 message
  pv1Message.setField('PID-3', dicomReport.patient.identifier.value); // Patient ID (MRN)
  pv1Message.setField('PV1-19', dicomReport.reporter.name.family + ' ' + dicomReport.reporter.name.given); // Reporter's Name

  // Set the report details
  const reportDetails = {
    'OBR-3': dicomReport.identifier.value, // Report ID (e.g., Study Instance UID)
    'OBX-2': dicomReport.result.status, // Result Status (e.g., "Final")
    'OBX-5': dicomReport.result.valueString, // Result Value
  };

  pv1Message.setSegment('OBR', reportDetails);
  pv1Message.setSegment('OBX', reportDetails);

  return pv1Message;
}
