using System;
using System.Linq;
using Hl7.Fhir.R4;

public class ProcedureValidator : IValidator<Procedure>
{
    public override void Validate(Procedure procedure)
    {
        // Check required elements and constraints specified by IHE MHD profile

        // 1. Ensure the Procedure resource has a valid identifier (id)
        if (!string.IsNullOrEmpty(procedure.Id))
        {
            Console.WriteLine("Procedure ID: " + procedure.Id);
        }
        else
        {
            throw new ValidationException("Procedure must have an ID");
        }

        // 2. Verify that the Procedure resource includes at least one participant with a valid role (participant.role)
        var participants = procedure.Participant;
        if (participants == null || !participants.Any(p => p.Role != null))
        {
            throw new ValidationException("Procedure must include at least one participant with a valid role");
        }

        // 3. Check that the Procedure resource has a valid code (code) and/or description
        if (!string.IsNullOrEmpty(procedure.Code?.Text) || !string.IsNullOrEmpty(procedure.Description))
        {
            Console.WriteLine("Procedure Code/Description: " + (procedure.Code?.Text ?? procedure.Description));
        }
        else
        {
            throw new ValidationException("Procedure must have a valid code or description");
        }

        // 4. Validate the Procedure resource's effective period (effective)
        var effective = procedure.Effective;
        if (effective == null || !IsEffectivePeriodValid(effective))
        {
            throw new ValidationException("Invalid Effective Period for Procedure");
        }

        // Helper method to check the validity of the effective period
        private bool IsEffectivePeriodValid(Period period)
        {
            return period.Start <= DateTime.Now && period.End >= DateTime.Now;
        }
    }
}
```
