            if (organization.Gender != null)
            {
                switch (organization.Gender.Value)
                {
                    case "male":
                        pid.Sex = Hl7CodeSystem.Male;
                        break;
                    case "female":
                        pid.Sex = Hl7CodeSystem.Female;
                        break;
                    default:
                        pid.Sex = Hl7CodeSystem.Unknown;
                        break;
                }
            }

            // Add any additional fields or mappings as needed

            return hl7Message.ToString();
        }
    }
