import { Procedure } from '@hl7/fhir-r4';
import { NK1Segment } from '@hl7/v2';

export function convertProcedureToNK1(procedure: Procedure): NK1Segment {
  const nk1 = new NK1Segment();

  // Extract patient information from the procedure
  const patient = procedure.patient;
  if (patient) {
    nk1.XPN[0].XPN.5 = patient.name.family; // Family name
    nk1.XPN[0].XPN.4 = patient.name.given.join(' '); // Given names
    nk1.XPN[0].XPN.3 = patient.gender === 'male' ? 'M' : (patient.gender === 'female' ? 'F' : 'U'); // Gender code
  }

  return nk1;
}
