import ca.uhn.fhir.context.FhirContext;
import ca.uhn.fhir.model.dstu2.resource.Acknowledgment;
import ca.uhn.fhir.model.primitive.StringDt;
import ca.uhn.fhir.parser.IParser;
import org.hl7.fhir.r4.model.MessageHeader;

public class FHIRAcknowledgmentHandler {

    private static final String FHIR_R4_VERSION = "http://hl7.org/fhir/R4";

    public void handleFHIRMessage(String fhirJson) {
        try {
            // Parse the FHIR JSON message
            IParser parser = FhirContext.forR4().newJsonParser();
            MessageHeader messageHeader = (MessageHeader) parser.parseResource(fhirJson);

            // Extract the acknowledgment from the message header
            Acknowledgment acknowledgment = extractAcknowledgment(messageHeader);

            if (acknowledgment != null) {
                handleAcknowledgment(acknowledgment);
            } else {
                System.out.println("No acknowledgment found in the FHIR message.");
            }
        } catch (Exception e) {
            // Handle any exceptions that occur during parsing or processing
            System.err.println("Error handling FHIR message: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private Acknowledgment extractAcknowledgment(MessageHeader messageHeader) {
        for (ca.uhn.fhir.model.dstu2.resource.Acknowledgment ack : messageHeader.getContained()) {
            if (ack instanceof ca.uhn.fhir.r4.model.Acknowledgment) {
                return (Acknowledge) ack;
            }
        }
        return null;
    }

    private void handleAcknowledgment(Acknowledgment acknowledgment) {
        // Process the acknowledgment here
        String acknowledgmentText = acknowledgment.getText();
        System.out.println("FHIR Acknowledgment: " + acknowledgmentText);
    }
