function convertCarePlanToFHl7(carePlan: CarePlan): Message {
  // Create a new HL7 v2 message with the correct message type (GT1)
  const hl7Message = new Message('GT1');

  // Map FHIR R4 elements to HL7 v2 fields
  hl7Message.addSegment(new Segment('PID', '1')); // Patient Identification
  hl7Message.addSegment(new Segment('PV1', '1')); // Visit/Encounter

  // Add patient information (PID segment)
  const pid = new PID();
  pid.setPatientIdentifier(carePlan.identifier[0].value);
  pid.setPatientName(carePlan.name[0].family + ', ' + carePlan.name[0].given.join(' '));
  hl7Message.addSegment(pid);

  // Add encounter information (PV1 segment)
  const pv1 = new PV1();
  pv1.setVisitNumber(carePlan.identifier[1] ? carePlan.identifier[1].value : '');
  hl7Message.addSegment(pv1);

  // Add care plan details
  hl7Message.addSegment(new Segment('DG1', '1')); // Diagnosis/Procedure
  const dg1 = new DG1();
  dg1.setDiagnosisCode(carePlan.intent);
  hl7Message.addSegment(dg1);

  return hl7Message;
}

