import { FHIRClient } from 'fhirclient';
import { ArgonautProfile } from './argonaut-profile'; // assume this is your Argonaut profile definition

export async function validateMedicationRequest(medicationRequest: any, argonautProfile: ArgonautProfile) {
  const client = new FHIRClient();
  const resource = await client.getResource(medicationRequest);

  if (!resource.isResource()) {
    throw new Error('Invalid FHIR resource');
  }

  // Check for required elements
  if (!medicationRequest.medicationCodeableConcept || !medicationRequest.dosageInstruction) {
    throw new Error('Missing required elements: medicationCodeableConcept or dosageInstruction');
  }

  // Validate against Argonaut profile constraints
  const argonautConstraints = argonautProfile.getConstraints();
  for (const constraint of argonautConstraints) {
    switch (constraint.type) {
      case 'range':
        if (!medicationRequest.dosageInstruction.some((instruction: any) => instruction.doseAndRate.range)) {
          throw new Error(`Missing dose and rate range for medication request`);
        }
        break;
      case 'codeableConcept':
        const codeableConcept = medicationRequest.medicationCodeableConcept;
        if (!codeableConcept.coding || !codeableConcept.coding.some((coding: any) => coding.system === constraint.system)) {
          throw new Error(`Invalid medication code system: ${constraint.system}`);
        }
        break;
      default:
        console.log(`Ignoring unknown constraint type: ${constraint.type}`);
    }
  }

  // Return a success message
  return 'Medication request validated successfully';
}
