import { MedicationRequest } from 'fhir-r4';
import { HL7v2Message } from 'hl7-v2';

export function convertMedicationRequestToFHl7V2(medicationRequest: MedicationRequest): HL7v2Message {
  const hl7Message = new HL7v2Message();

  // Map FHIR resource to HL7 v2 segments
  hl7Message.MSH.setField('MSH-3', 'FHIR'); // Message type (e.g., ADT^A01)
  hl7Message.MSH.setField('MSH-4', 'FHIR Application');
  hl7Message.MSH.setField('MSH-5', 'FHIR Server');

  hl7Message.PID.setField('PID-3', medicationRequest.patient.identifier.value); // Patient ID
  hl7Message.PID.setField('PID-5', `${medicationRequest.patient.name.family} ${medicationRequest.patient.name.given.join(' ')}`); // Patient Name

