  hl7Message.OBR.setField('OBR-2', medicationRequest.medicationCodeableConcept.coding[0].code); // Medication Code

  hl7Message.EVN.setField('EVN-1', 'A01'); // Event type (e.g., ADT^A01)

  return hl7Message;
}
