using Hl7.Fhir.R4.Model.DiagnosticReport;
using Hl7.Fhir.R4.Model.ResourceTypes;

namespace FHIRtoHL7v2GT1Converter
{
    public class DiagnosticReportToFHIRv2GT1Converter
    {
        private readonly DiagnosticReport _diagnosticReport;

        public DiagnosticReportToFHIRv2GT1Converter(DiagnosticReport diagnosticReport)
        {
            _diagnosticReport = diagnosticReport;
        }

        public string ConvertToHL7v2GT1()
        {
            // Create an empty HL7 message with the correct message type (GT1)
            var hl7Message = new StringBuilder();
            hl7Message.Append("MSH|^~\\&|FHIR-Converter|||");
            hl7Message.Append("|");

            // Add the PID segment
            hl7Message.Append("PID||");
            hl7Message.Append(_diagnosticReport.Patient?.Id?.Value ?? "Unknown Patient ID");
            hl7Message.Append("^");

            // Add the OBX segments for each observation in the DiagnosticReport
            foreach (var observation in _diagnosticReport.Observation)
