                hl7Message.Append("OBX|1||");
                hl7Message.Append(observation.Code?.Coding[0]?.Code ?? "Unknown Code");
                hl7Message.Append("^");

                // Add the value of the observation
                if (observation.ValueQuantity != null)
                {
                    hl7Message.Append(observation.ValueQuantity.Value.ToString());
                    hl7Message.Append("^");
                }
            }

            return hl7Message.ToString();
        }
    }
}
