function validateCondition(condition) {
  // Check if the condition has at least one identifier (e.g., LOINC code)
  if (!condition.identifier || !condition.identifier.length) return false;

  const usCoreProfile = {
    'us-core-condition': {
      'code': ['http://snomed.org/ctv3/ClinicalFindings'],
      'system': 'http://loinc.org'
    }
  };

  // Check if the condition has a code that matches one of the US Core profile's codes
  const code = condition.code.coding[0];
  if (!usCoreProfile['us-core-condition'].code.includes(code.system) ||
      !usCoreProfile['us-core-condition'].code.some((code) => code === code.code)) {
    return false;
  }

  // Check if the condition has a status of "active" or "in-progress"
  const status = condition.status;
  if (!['active', 'in-progress'].includes(status)) {
    return false;
  }

  // Additional checks can be added here, such as:
  // - Checking for presence of at least one patient (e.g., reference to a Patient resource)
  // - Verifying the condition's category is "problem-list-item" or similar

  return true; // If all checks pass, the condition is valid according to US Core profile
}
