import { FhirR4 } from 'fhir-r4';
import { Hl7v2 } from 'hl7-v2';

// Define a function to convert a FHIR R4 Practitioner resource to an HL7 v2 EVN message
function practitionerToEvn(practitioner: FhirR4.Practitioner): Hl7v2.Message {
  // Create a new HL7 v2 message with the correct message type (EVN)
  const evnMessage = new Hl7v2.Message('EVN');

  // Map Practitioner's name to PID-5 (Patient Name) in EVN
  evnMessage.addSegment(new Hl7v2.Segment(Hl7v2.SegmentType.PID));
  evnMessage.getSegment(Hl7v2.SegmentType.PID).addField('PID-5', practitioner.name[0].given.join(' ') + ' ' + practitioner.name[0].family);

  // Map Practitioner's birth date to EVN-1 (Event Date/Time)
