import { Hl7v2Message } from 'hl7-v2';

export function convertFhirToHl7(fhirPatient: FhirR4Patient): Hl7v2Message {
  const hl7Message = new Hl7v2Message();

  // PID segment
  hl7Message.addSegment('PID');
  hl7Message.getSegment('PID').addField('3', fhirPatient.identifier[0].system); // Patient ID (MRN)
  hl7Message.getSegment('PID').addField('5', fhirPatient.name[0].given.join(' ') + ' ' + fhirPatient.name[0].family); // Name
  hl7Message.getSegment('PID').addField('7', fhirPatient.birthDate.toString()); // Birth Date

  // PV1 segment (optional)
  if (fhirPatient.gender) {
    hl7Message.addSegment('PV1');
    hl7Message.getSegment('PV1').addField('5', fhirPatient.gender === 'male' ? 'M' : 'F'); // Gender
  }

  return hl7Message;
}
```
