import { FhirR4 } from 'fhir-r4';
import { Hl7v2 } from 'hl7-v2';

export function convertFhirEncounterToFhirHl7(fhirResource: FhirR4.Encounter): Hl7v2.Message {
  const hl7Message = new Hl7v2.Message();

  // Map Encounter.id to PID-3 (Patient Identifier)
  hl7Message.addSegment(new Hl7v2.PID({
    patientId: fhirResource.id,
  }));

  // Map Encounter.status to PV1-4 (Visit Reason Code)
  switch (fhirResource.status) {
    case 'planned':
      hl7Message.addSegment(new Hl7v2.PV1({
        visitReasonCode: 'P', // Planned
      }));
      break;
    case 'in-progress':
      hl7Message.addSegment(new Hl7v2.PV1({
        visitReasonCode: 'I', // In Progress
      }));
      break;
    default:
      throw new Error(`Unsupported Encounter status: ${fhirResource.status}`);
  }

  // Map Encounter.type to PV1-5 (Service User)
  hl7Message.addSegment(new Hl7v2.PV1({
    serviceUser: fhirResource.type?.coding[0]?.code,
  }));

  return hl7Message;
}
