// Function to convert a FHIR R4 ServiceRequest to an HL7 v2 OBR message
function serviceRequestToObr(serviceRequest: ServiceRequest): OBR {
  const obr = new OBR();

  // Map the FHIR resource's identifier to the HL7 v2 PID-3 (Patient ID)
  obr.PID_3 = serviceRequest.identifier.value;

  // Map the FHIR resource's code to the HL7 v2 OBR-4 (Observation Code)
