  // Map the FHIR resource's description to the HL7 v2 OBR-5 (Observation Description)
  obr.OBR_5 = serviceRequest.description;

  // Map the FHIR resource's performer to the HL7 v2 OBR-16 (Performer ID)
  obr.OBR_16 = serviceRequest.performer[0].reference.split('/').pop();

  return obr;
}

