    public static string ConvertConditionToHL7v2PV1(Condition condition)
    {
        // Create a new HL7 v2 PV1 segment
        var pv1Segment = new Segment("PV1");

        // Map the FHIR Condition resource to the HL7 PV1 segment
        if (condition.Code != null && condition.Code.Text != null)
        {
            // Set the Observation Identifier (OBX-3) with the condition code
            pv1Segment.Add(new Field("OBX", "3", condition.Code.Text));
        }

