                case "Mild":
                    pv1Segment.Add(new Field("PV1-10", "M")); // Mild: M=Minor, S=Severe, N=None
                    break;
                case "Moderate":
                    pv1Segment.Add(new Field("PV1-10", "S")); // Moderate: S=Severe
                    break;
                case "Severe":
                    pv1Segment.Add(new Field("PV1-10", "N")); // Severe: N=None
                    break;
            }
        }

        return pv1Segment.ToString();
    }
}
