export async function validateDocumentReference(
  documentReference: Fhir.DocumentReference,
  argonautProfile: ArgonautProfile,
): Promise<void> {
  // Check if the document reference has a valid identifier
  const identifier = documentReference.identifier;
  if (!identifier || !identifier.system) {
    throw new Error('Invalid Document Reference Identifier');
  }

  // Check if the document reference has a valid content type
  const contentType = documentReference.content[0].contentType;
  if (!contentType || !argonautProfile.allowedContentTypes.includes(contentType)) {
    throw new Error(`Unsupported Content Type: ${contentType}`);
  }

  // Check if the document reference has a valid format
  const format = documentReference.format;
  if (!format || !argonautProfile.allowedFormats.includes(format)) {
    throw new Error(`Invalid Document Reference Format: ${format}`);
  }

  // Check if the document reference has a valid title
  const title = documentReference.title;
  if (!title) {
    throw new Error('Missing Document Reference Title');
  }

  // Check if the document reference has a valid description
  const description = documentReference.description;
  if (description && !argonautProfile.allowedDescriptions.includes(description)) {
    throw new Error(`Invalid Document Reference Description: ${description}`);
  }
}
```
