public class PatientMatchingService {
    private static final String API_KEY = "YOUR_API_KEY_HERE";
    private static final String ENDPOINT_URL = "/soap/1.0/PatientMatching";

    public List<Patient> matchPatients(List<Patient> patients) throws Exception {
