            public void intercept(Message message) throws Exception {
                message.setProperty("http.headers", headers);
            }
        });

        // Create a PatientMatching instance and call the matchPatients method
        PatientMatching patientMatcher = (PatientMatching) factory.create();

        List<Patient> matchedPatients = new ArrayList<>();
        for (Patient patient : patients) {
            try {
                Patient matchedPatient = patientMatcher.matchPatient(patient);
                if (matchedPatient != null) {
                    matchedPatients.add(matchedPatient);
                }
            } catch (Exception e) {
                // Handle errors
                System.out.println("Error matching patient: " + e.getMessage());
            }
        }

        return matchedPatients;
    }
