import okhttp3.*;
import java.io.IOException;
import org.json.JSONObject;

public class InterfaceMonitor {
    private static final String BASE_URL = "https://api.meditech.com";
    private static final String API_KEY = "your_api_key"; // Replace with your actual API key

    public static void main(String[] args) throws IOException, InterruptedException {
        OkHttpClient client = new OkHttpClient();

        // Step 1: Get the list of interfaces using the bulk data API
        Request request = new Request.Builder()
                .url(BASE_URL + "/api/v2/integrations/monitoring/bulk")
                .header("Authorization", "Bearer " + API_KEY)
                .get()
                .build();

        Response response = client.newCall(request).execute();

        if (!response.isSuccessful()) {
            System.out.println("Failed to retrieve interfaces: " + response.code());
            return;
        }

        String responseBody = response.body().string();
        JSONObject jsonObject = new JSONObject(responseBody);

        // Step 2: Extract the list of interfaces from the JSON response
        JSONArray interfaceList = jsonObject.getJSONArray("interfaces");

        for (int i = 0; i < interfaceList.length(); i++) {
            JSONObject interfaceObj = interfaceList.getJSONObject(i);
            String interfaceId = interfaceObj.getString("id");
            System.out.println("Interface ID: " + interfaceId);

            // Step 3: Monitor the status of each interface
            request = new Request.Builder()
                    .url(BASE_URL + "/api/v2/integrations/monitoring/status?interface_id=" + interfaceId)
                    .header("Authorization", "Bearer " + API_KEY)
                    .get()
                    .build();

            response = client.newCall(request).execute();

            if (!response.isSuccessful()) {
                System.out.println("Failed to retrieve status for interface ID: " + interfaceId);
                continue;
            }

            responseBody = response.body().string();
            jsonObject = new JSONObject(responseBody);

            String status = jsonObject.getString("status");
            System.out.println("Interface Status: " + status);
        }
    }
}
