function getAccessToken() {
    // Replace with your client ID and secret
    const clientId = 'your_client_id';
    const clientSecret = 'your_client_secret';

    // Construct the request body for the token endpoint
    const requestBody = `
        <soap:Envelope xmlns:soap="http://www.w3.org/2003/05/soap-envelope/" 
                         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
            <soap:Body>
                <oauth2:grant_type xmlns:oauth2="urn:ietf:params:oauth:grant-type:client-credentials">
                    <oauth2:client_id>${clientId}</oauth2:client_id>
