                </oauth2:grant_type>
            </soap:Body>
        </soap:Envelope>
    `;

    // Make the POST request to obtain an access token
    const response = await fetch('https://api.cerner.com/oauth/token', {
        method: 'POST',
        headers: { 'Content-Type': 'text/xml' },
        body: requestBody,
    });

