using System;
using System.Collections.Generic;

public class Node
{
    public int value;
    public List<Node> neighbors = new List<Node>();
}

public class Graph
{
    private Dictionary<int, Node> nodes;

    public Graph(int n)
    {
        nodes = new Dictionary<int, Node>();
        for (int i = 0; i < n; i++)
        {
            nodes.Add(i, new Node { value = i });
        }
    }

    public void AddEdge(int u, int v)
    {
        if (!nodes.ContainsKey(u))
        {
            nodes.Add(u, new Node());
        }
        if (!nodes.ContainsKey(v))
        {
            nodes.Add(v, new Node());
        }
        nodes[u].neighbors.Add(nodes[v]);
        nodes[v].neighbors.Add(nodes[u]);
    }

    public void BFS(int start)
    {
        Queue<Node> queue = new Queue<Node>();
        Dictionary<int, bool> visited = new Dictionary<int, bool>();

        // Initialize the queue with the starting node
        queue.Enqueue(nodes[start]);

        while (queue.Count > 0)
        {
            Node current = queue.Dequeue();

            if (!visited[current.value])
            {
                visited[current.value] = true;

                // Enqueue all neighbors of this node
                foreach (Node neighbor in current.neighbors)
                {
                    if (!visited[neighbor.value])
                    {
                        queue.Enqueue(neighbor);
                    }
                }
            }
        }
    }

    public static void Main(string[] args)
    {
        Graph graph = new Graph(4); // Create a graph with 4 nodes

        // Add edges to the graph
        graph.AddEdge(0, 1);
        graph.AddEdge(0, 2);
        graph.AddEdge(1, 3);

        // Perform BFS starting from node 0
        graph.BFS(0);

        Console.WriteLine("Visited nodes: " + string.Join(", ", visited.Select(kvp => kvp.Key.ToString()).ToArray()));
    }
}
