```javascript
function retry(fn, maxAttempts = 5, initialDelay = 1000) {
    let attempt = 0;
    let delay = initialDelay;

    while (attempt < maxAttempts) {
        try {
            fn();
            break; // If the function succeeds, exit the loop
        } catch (error) {
            if (error.name === 'TimeoutError') { // Handle timeout errors specifically
                console.error(`Timeout occurred: ${error.message}`);
                attempt++;
                delay *= 2;
                continue; // Retry with increased delay
            }

            console.error(`Error occurred: ${error.message}`);
            attempt++;

            // Exponential backoff (increase the delay by a factor of 2 each time)
            setTimeout(() => {
                retry(fn, maxAttempts, delay * 2);
            }, delay);
        }
    }

    return; // If all attempts fail, exit without throwing an error
}

// Example usage:
