    console.log("Attempting to perform some operation...");
    try {
        // Simulate a successful operation
        console.log("Operation succeeded!");
    } catch (error) {
        retry(() => {
            // Perform the operation that may throw errors
            console.log("Operation failed, retrying...");
        }, 5, 1000); // Max attempts: 5, initial delay: 1 second
    }
}

example();
```

