```javascript
function bfs(graph, startNode) {
  let visited = new Set();
  let queue = [[startNode]];

  while (queue.length > 0) {
    let currentLevel = [];
    for (let i = 0; i < queue.length; i++) {
      let node = graph[queue[i]];
      if (!visited.has(node)) {
        visited.add(node);
        currentLevel.push(...node.children); // Assuming 'children' is an array of adjacent nodes
      }
    }
    queue = [currentLevel];
  }

  return visited;
}
```

