function mergeSort(arr: Array<T>): Array<T> {
  if (arr.length <= 1) return arr;

  const mid = Math.floor((arr.length + 1) / 2);
  const left = mergeSort(arr.data.slice(0, mid));
  const right = mergeSort(arr.data.slice(mid));

  return [...left, ...right].sort((a, b) => a - b);
