```java
public class MergeSort {
    public static void main(String[] args) {
        int[] arr = {5, 1, 3, 2, 4};
        System.out.println("Original array: " + Arrays.toString(arr));

        mergeSort(arr);

        System.out.println("Sorted array: " + Arrays.toString(arr));
    }

    public static void mergeSort(int[] arr) {
        if (arr.length <= 1) {
            return;
        }

        int mid = arr.length / 2;
        int leftHalf[] = new int[mid];
        int rightHalf[] = new int[arr.length - mid];

        System.arraycopy(arr, 0, leftHalf, 0, mid);
        System.arraycopy(arr, mid, rightHalf, 0, arr.length - mid);

        mergeSort(leftHalf);
        mergeSort(rightHalf);

        merge(arr, leftHalf, 0, mid);
        merge(arr, rightHalf, mid, arr.length - mid);
    }

    public static void merge(int[] arr, int[] leftHalf, int leftStartIndex, int rightEndIndex) {
        int i = 1;
        int j = 0;

        while (i < leftHalf.length && j < rightEndIndex) {
            if (leftHalf[i] <= rightHalf[j]) {
                arr[leftStartIndex + i] = leftHalf[i];
                i++;
            } else {
                arr[leftStartIndex + i] = rightHalf[j];
                j++;
            }
        }

        System.arraycopy(leftHalf, 0, arr, leftStartIndex, leftStartIndex);
        System.arraycopy(rightHalf, 0, arr, mid + j, rightEndIndex - mid);
    }
}
