Here's an implementation of Dijkstra's algorithm in TypeScript:

```typescript
interface Node {
  id: number;
  distance: number;
}

type Graph = Record<number, Array<Node>>;

function dijkstra(graph: Graph, startNodeId: number): Node[] {
  const nodes = Object.keys(graph).map((nodeId) => ({
    id: parseInt(nodeId),
    distance: Infinity,
  }));

  const startNode = nodes.find((node) => node.id === startNodeId);
  if (!startNode) throw new Error("Start node not found");

  startNode.distance = 0;

  const heap: { [key: number]: Node } = {};
  heap[startNode.id] = startNode;

  while (heap.size > 0) {
    let minDistanceNode = Object.values(heap).reduce((a, b) => a[1].distance < b[1].distance ? a : b);

    if (!minDistanceNode) break;

    const currentNodeId = minDistanceNode.id;
    const currentDistance = minDistanceNode.distance;

    for (const neighbor of graph[currentNodeId]) {
      if (heap.hasOwnProperty(neighbor.id)) continue; // already visited
      const newDistance = currentDistance + 1; // edge weight is assumed to be 1

      if (newDistance < neighbor.distance) {
        heap[neighbor.id] = { id: neighbor.id, distance: newDistance };
      }
    }

    delete heap[currentNodeId];
  }

  return Object.values(nodes).filter((node) => node.id in heap);
}

// Example usage:
const graph: Graph = {
  "0": [{ id: 1 }, { id: 2 }],
  "1": [{ id: 3 }, { id: 4 }],
  "2": [{ id: 5 }],
  "3": [],
  "4": [],
  "5": [],
};

const result = dijkstra(graph, "0");
console.log(result);
```

This implementation uses a priority queue (min-heap) to efficiently find the shortest path from the start node. The time complexity is O(n log n), where n is the number of nodes in the graph.

Note that this implementation assumes unweighted graphs and edge weights are 1. If you need to handle weighted edges or directed graphs, additional modifications will be required.

