Here's an example of how to implement Dijkstra's algorithm in JavaScript:

```javascript
function dijkstra(graph, startNode) {
  const distances = Object.keys(graph).map((node) => ({ [node]: Infinity }));
  const parentMap = Object.keys(graph);

  // Initialize the distance and parent maps
  for (let node of Object.keys(graph)) {
    if (node === startNode) {
      distances[node] = 0;
    }
  }

  // Priority queue: [distance, node]
  const priorityQueue = [[0, startNode]];

  while (priorityQueue.length > 0) {
    let [currentDistance, currentNode] = priorityQueue.shift();

    if (currentDistance > distances[currentNode]) continue;

    for (let neighbor of graph[currentNode]) {
      const newDistance = currentDistance + graph[currentNode][neighbor];
      if (newDistance < distances[neighbor]) {
        parentMap[neighbor] = currentNode;
        distances[neighbor] = newDistance;
        priorityQueue.push([newDistance, neighbor]);
      }
    }
  }

  return parentMap;
}

// Example usage:
const graph = {
  'A': {'B': 2, 'C': 3},
  'B': {'C': 1, 'D': 4},
  'C': {'D': 5},
  'D': {}
};

const startNode = 'A';
const result = dijkstra(graph, startNode);

console.log(result);
```

