Here's an implementation of the A* algorithm in TypeScript:

```typescript
interface Node {
  x: number;
  y: number;
  f: number; // cost from start to this node
  g: number; // cost from current node to end node
  h: number; // heuristic estimate of distance from current node to end node
}

function AStar(nodeStart: Node, nodeEnd: Node, nodes: Node[]) {
  let openSet = [nodeStart];
  let closedSet = [];

  while (openSet.length > 0) {
    let currentNode = openSet[0];

    if (currentNode.x === nodeEnd.x && currentNode.y === nodeEnd.y) {
      return currentNode;
    }

    for (let i = 0; i < nodes.length; i++) {
      if (!closedSet.includes(nodes[i]) && nodes[i].f < currentNode.f) {
        openSet.unshift(nodes[i]);
      }
    }

    closedSet.push(currentNode);

    let neighbors: Node[] = [];
    // Add neighbor nodes here
    for (let i = 0; i < nodes.length; i++) {
      if (!closedSet.includes(nodes[i]) && Math.abs(nodeStart.x - nodes[i].x) + Math.abs(nodeStart.y - nodes[i].y) <= currentNode.f) {
        neighbors.push(nodes[i]);
      }
    }

    for (let neighbor of neighbors) {
      let tempG = currentNode.g + Math.abs(neighbor.x - currentNode.x) + Math.abs(neighbor.y - currentNode.y);
      if (tempG < neighbor.g) {
        neighbor.g = tempG;
        openSet.unshift(neighbor);
      }
    }
  }

  return null; // no path found
}
```

This implementation uses a priority queue to store the nodes with their f-values, which is updated whenever a better path to a node is found. The algorithm also keeps track of the closed set and the open set.

The time complexity of this A* algorithm is O(n log n), where n is the number of nodes in the graph.

