    this.cacheMap.set(key, { key, value, timestamp: now });
    this.evictionQueue.add(key);
  }

  remove(key: string): void {
    const item = this.cacheMap.get(key);
    if (item) {
      this.cacheMap.delete(key);
      this.evictionQueue.delete(key);
    }
  }
}
