import time
from typing import Optional

class Retry:
    def __init__(self, max_attempts: int = 5, initial_backoff_seconds: float = 1.0):
        self.max_attempts = max_attempts
        self.initial_backoff_seconds = initial_backoff_seconds
        self.current_attempt = 0

    def retry(self, func: callable, *args, **kwargs) -> Optional[dict]:
        attempts = {}
        for i in range(self.max_attempts):
            attempt = {
                'status': 'failed',
                'error': None,
                'result': None
            }
            try:
                result = func(*args, **kwargs)
                attempt['status'] = 'success'
                attempt['result'] = result
            except Exception as e:
                attempt['status'] = 'failed'
                attempt['error'] = str(e)

            if attempt['status'] == 'success':
                return attempt

            # Backoff and wait before retrying
            backoff_seconds = self.initial_backoff_seconds * (2 ** i)
            time.sleep(backoff_seconds)
            self.current_attempt += 1

        attempts[self.current_attempt] = attempt
        return None

    def get_attempts(self) -> dict:
        return self.attempts

# Example usage:
