interface CacheItem {
  key: string;
  value: any;
  timestamp: number;
}

class LRUCache {
  private cacheMap: Map<string, CacheItem>;
  private linkedList: Node[];

  constructor(size: number) {
    this.cacheMap = new Map();
    this.linkedList = [];
  }

  get(key: string): CacheItem | null {
    const item = this.cacheMap.get(key);
    if (item) {
      // Update the timestamp and move to the end of the linked list
      item.timestamp = Date.now();
      this.moveNodeToEnd(item.node);
    }
    return item;
  }

  set(key: string, value: any): void {
    const now = Date.now();
    const node = new Node({ key, value, timestamp: now });
    this.cacheMap.set(key, node);

    // If the cache size exceeds the limit, remove the least recently used item
    if (this.cacheMap.size > this.size) {
      const lruItem = this.getLeastRecentlyUsed();
      this.removeNode(lruItem.node);
    }

    this.linkedList.push(node);
  }

  private getLeastRecentlyUsed(): CacheItem | null {
    let leastRecentlyUsed: CacheItem | null = null;
    for (const item of this.linkedList) {
      if (!leastRecentlyUsed || item.timestamp < leastRecentlyUsed.timestamp) {
        leastRecentlyUsed = item;
      }
    }
    return leastRecentlyUsed;
  }

  private removeNode(node: Node): void {
    const index = this.linkedList.indexOf(node);
    if (index !== -1) {
      this.linkedList.splice(index, 1);
    }
  }

  private moveNodeToEnd(node: Node): void {
    let i = 0;
    for (const item of this.linkedList) {
      if (item === node) break;
      i++;
    }
    this.linkedList.splice(i + 1, 0, node);
  }
}

