```csharp
public class CircuitBreaker
{
    private int maxAttempts;
    private int currentAttempt;

    public CircuitBreaker(int maxAttempts)
    {
        this.maxAttempts = maxAttempts;
        this.currentAttempt = 0;
    }

    public bool TryAction(Action action)
    {
        try
        {
            if (currentAttempt >= maxAttempts)
                throw new Exception("Maximum attempts exceeded.");

            currentAttempt++;
            action();
            return true;
        }
        catch (Exception e)
        {
            if (e is CircuitBreakerException)
                return false;

            // Log the error and wait for a while before retrying
            Console.WriteLine($"Error: {e.Message}");
            Thread.Sleep(5000); // Wait 5 seconds

            return TryAction(action);
        }
    }

    public void Reset()
    {
        currentAttempt = 0;
    }
}
```

