```java
import java.util.*;

public class LRUCache {
    private int capacity;
    private Map<String, String> map;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        map = new HashMap<>();
    }

    public void put(String key, String value) {
        List<Map.Entry<String, String>> entries = new ArrayList<>(map.entrySet());
        Collections.sort(entries, (e1, e2) -> {
            long lastAccessedTime1 = System.currentTimeMillis() - Long.parseLong(e1.getValue().split(",")[0]);
            long lastAccessedTime2 = System.currentTimeMillis() - Long.parseLong(e2.getValue().split(",")[0]);
            return Integer.compare((int) (lastAccessedTime1 / 1000), (int) (lastAccessedTime2 / 1000));
        });
        if (entries.size() > capacity) {
            map.remove(entries.get(entries.size() - 1).getKey());
        }
        map.put(key, System.currentTimeMillis() + "," + value);
    }

    public String get(String key) {
        return map.getOrDefault(key, "");
    }
}
```

