```typescript
class Queue {
  private array: any[];

  constructor() {
    this.array = [];
  }

  public enqueue(element: any): void {
    let index = this.array.length;
    while (index < this.array.length) {
      if (!this.array[this.array.length - 1]) break;
      index++;
    }
    this.array.push(element);
  }

  public dequeue(): any | null {
    return this.array.shift();
  }
}

function bfs(start: any, graph: Map<any, Set<any>>, visited: Set<any>): any[] {
  let queue = new Queue();
  queue.enqueue(start);
  visited.add(start);

  while (queue.array.length > 0) {
    let node = queue.dequeue() as any;

    for (let neighbor of graph.get(node)) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.enqueue(neighbor);
      }
    }
  }

  return this.array.filter((element: any) => element !== null && element !== undefined).map((element: any) => element as any[]);
}

