public class BinarySearch {
    public static int findTarget(int[] array, int target) {
        int low = 0;
        int high = array.length - 1;

        while (low <= high) {
            int mid = (low + high) / 2; // Calculate the middle index

            if (array[mid] == target) { // If we find the target, return its index
                return mid;
            } else if (target < array[mid]) { // If the target is smaller than the current element, search in the lower half
                high = mid - 1;
            } else { // If the target is larger than the current element, search in the upper half
                low = mid + 1;
            }
        }

        return -1; // Return -1 if no match is found
    }
}
