        {
            // Update the cache and mark it as recently used
            _cache[key] = value;
            _recentlyUsed.Enqueue(key);
        }
        else
        {
            // Add a new item to the cache and mark it as recently used
            _cache.Add(key, value);
            _recentlyUsed.Enqueue(key);

            // If the cache exceeds its maximum size, remove the least recently used item
            if (_cache.Count > _maxSize)
            {
                string leastRecentlyUsed = _recentlyUsed.Dequeue();
                _cache.Remove(leastRecentlyUsed);
            }
        }
    }

    public T Get(string key)
    {
        // Check if the cache contains the requested item
        return _cache.TryGetValue(key, out T value) ? value : default(T);
    }
}
