public class Dijkstra {
    public static void main(String[] args) {
        // Create a graph with 4 nodes and edges
        List<Node> nodes = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            nodes.add(new Node(i));
        }

        // Add edges to the graph
        nodes.get(0).addEdge(nodes.get(1), 2); // Edge from node 0 to node 1 with weight 2
        nodes.get(1).addEdge(nodes.get(2), 3); // Edge from node 1 to node 2 with weight 3
        nodes.get(2).addEdge(nodes.get(3), 4); // Edge from node 2 to node 3 with weight 4

        // Run Dijkstra's algorithm
        Node startNode = nodes.get(0);
        List<Node> shortestPaths = dijkstra(startNode);

        for (Node path : shortestPaths) {
            System.out.println("Path: " + path.getPath());
        }
    }

    public static List<Node> dijkstra(Node startNode) {
        // Initialize distances to all nodes
        double[] distances = new double[nodes.size()];
        Arrays.fill(distances, Double.POSITIVE_INFINITY);
        distances[startNode.getId()] = 0;

        // Create a priority queue and add the starting node
        PriorityQueue<Node> queue = new PriorityQueue<>();
        queue.add(startNode);

        List<Node> shortestPaths = new ArrayList<>();

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            if (current.getId() == nodes.size() - 1) { // Reached destination node
                break;
            }

            for (Edge edge : current.getEdges()) {
                Node neighbor = edge.getToNode();
                double distanceThroughCurrent = distances[current.getId()] + edge.getWeight();

                if (distanceThroughCurrent < distances[neighbor.getId()]) {
                    distances[neighbor.getId()] = distanceThroughCurrent;
                    queue.add(neighbor);
                }
            }
        }

        return shortestPaths;
    }
}

