        mergeSort(arr, mid + 1, arr.length - 1);

        // merge the two halves
        for (int i = 0; i <= mid; i++) {
            System.arraycopy(arr, leftHalf + i, arr, rightHalf - mid + i + 1, 1);
        }

        System.arraycopy(arr, 0, arr, 0, leftHalf);
    }

    public static void merge(int[] arr, int left, int right) {
        int[] temp = new int[arr.length];
        int i = j = k = 0;

        while (i < left && j < right) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
            }
        }

        System.arraycopy(arr, left, temp, k, left - left);
        System.arraycopy(arr, right, temp, k + left, right - right);

        for (int i = 0; i < arr.length; i++) {
            arr[i] = temp[i];
        }
    }
}
```

