```java
import java.util.ArrayList;
import java.util.List;

public class Node {
    int value;
    List<Node> neighbors = new ArrayList<>();

    public Node(int val) {
        this.value = val;
    }
}

public class BFS {
    public static void bfs(Node root, int target) throws Exception {
        if (root.value == target) return; // Early exit if we've found the target

        Queue<Node> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (Node neighbor : current.neighbors) {
                if (neighbor.value < target && !hasVisited(neighbor, target)) { // Only enqueue nodes with smaller values
                    queue.add(neighbor);
                }
            }
        }

        throw new Exception("Target not found");
    }

    private static boolean hasVisited(Node node, int target) {
        return node.value == target || node.neighbors.isEmpty(); // Mark as visited if we've reached the target or a leaf node
    }
}
```

