import java.util.PriorityQueue;

public class Dijkstra {
    public static void main(String[] args) {
        // Create a graph with 4 nodes and edges
        int[][] graph = new int[5][];
        for (int i = 0; i < 5; i++) {
            graph[i] = new int[5];
            Arrays.fill(graph[i], -1); // Initialize all distances to -1
        }
        graph[0][1] = 2;
        graph[0][2] = 3;
        graph[1][3] = 4;
        graph[2][3] = 5;

        int[] dist = new int[5];
        for (int i = 0; i < 5; i++) {
            dist[i] = -1; // Initialize all distances to -1
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();
        Node node0 = new Node(0, 0); // Start from node 0 with distance 0
        pq.put(node0);
        dist[0] = 0;

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            int u = current.getU();

            for (int v = 0; v < graph[u].length; v++) {
                if (graph[u][v] != -1) { // If there's an edge from u to v
                    int distance = dist[u] + graph[u][v]; // Calculate the new distance

                    if (dist[v] == -1 || distance < dist[v]) { // Update the distance if it's better
                        dist[v] = distance;
                        pq.put(new Node(distance, v)); // Add to priority queue
                    }
                }
            }
        }

        System.out.println("Shortest distances from node 0:");
        for (int i = 0; i < 5; i++) {
            System.out.print("Node " + i + ": " + dist[i] + "\n");
        }
    }
}

