Merge sort is a divide-and-conquer algorithm that sorts an array by recursively dividing it into smaller subarrays until each subarray has one or two elements, then merging them back together.

Here's the implementation:
```csharp
using System;
using System.Collections.Generic;

public class MergeSort
{
    public static void Sort<T>(T[] arr) where T : IComparable
    {
        if (arr.Length <= 1)
            return; // already sorted

        int mid = Array.IndexOf(arr, null); // find the middle index
        T[] left = new T[mid];
        T[] right = new T[arr.Length - mid];

        Array.Copy(arr, 0, left, 0, mid);
        Array.Copy(arr, mid + 1, right, 0, arr.Length - mid - 1);

        Sort(left);
        Sort(right);

        // merge the sorted subarrays
        int i = 0;
        for (int j = 0; j < arr.Length; j++)
        {
            if (i >= left.Length)
                break;

            if ((j == 0 || left[i].CompareTo(arr[j]) > 0) && 
                (i == 0 || right[0].CompareTo(left[i]) > 0))
            {
                arr[j] = left[i];
                i++;
            }
            else
            {
                arr[j] = right[0];
                right.RemoveAt(0);
            }
        }

        for (int j = 0; j < right.Length; j++)
        {
            arr[arr.Length - 1 - j] = right[j];
        }
    }
}
```
**O(1) Complexity**

The merge sort algorithm has a time complexity of O(n log n), where n is the number of elements in the array. This means that as the size of the input increases, the running time will increase proportionally to the logarithm of the input size.

