```javascript
function bfs(graph, startNode) {
  let visited = new Set();
  let queue = [[startNode]];

  while (queue.length > 0) {
    let [node] = queue.shift();

    if (!visited.has(node)) {
      visited.add(node);

      for (let neighbor of graph[node]) {
        if (!visited.has(neighbor)) {
          queue.push([neighbor]);
        }
      }
    }
  }

  return visited;
}

// Example usage:
