```typescript
interface Node {
  x: number;
  y: number;
  f: number; // total cost from start to node
  g: number; // cost from current node to goal
  h: number; // heuristic estimate of distance from current node to goal
}

function AStar<T extends Node>(start: T, goal: T, openList: Array<T>, closedSet: Set<T>) {
  let openPriorityQueue = [...openList];
  openPriorityQueue.sort((a, b) => a.f - b.f);

  while (openPriorityQueue.length > 0) {
    const current = openPriorityQueue[0];

    if (closedSet.has(current)) continue;

    if (current === goal) return current;

    // Move to next node
    let neighbors: Array<T> = [];
    for (let direction of ['up', 'down', 'left', 'right']) {
      const [dx, dy] = direction === 'up' ? [-0, 1] : direction === 'down' ? [0, -1] : 
        direction === 'left' ? [-1, 0] : [1, 0];
      const nextNode: T = { x: current.x + dx, y: current.y + dy };
      if (!closedSet.has(nextNode)) {
        neighbors.push(nextNode);
      }
    }

    // Update g and h values
    for (let neighbor of neighbors) {
      const tentativeG = current.g + 1;
      const actualG = openList.find((node: T) => node.x === neighbor.x && node.y === neighbor.y)?.g || Infinity;

      if (tentativeG < actualG) {
        neighbor.g = tentativeG;
        openPriorityQueue.push(neighbor);
      }
    }

    // Update h value
    for (let neighbor of neighbors) {
      const heuristicH = Math.abs(current.x - goal.x) + Math.abs(current.y - goal.y);
      if (!closedSet.has(neighbors[0])) {
        openPriorityQueue[0].h = heuristicH;
      }
    }

    // Remove current node from open list
    const index = openList.findIndex((node: T) => node === current);
    if (index !== -1) {
      openList.splice(index, 1);
    }
  }

  return null; // no path found
}
