import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class ThreadPoolTest {

    @Test
    public void testThreadPool() {
        // Create a thread pool with 2 threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Submit some tasks to the thread pool
        Future<?> future1 = executor.submit(() -> {
            try {
                Thread.sleep(1000);
                System.out.println("Task 1 completed");
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        Future<?> future2 = executor.submit(() -> {
            try {
                Thread.sleep(2000);
                System.out.println("Task 2 completed");
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        // Wait for the tasks to complete
        try {
            executor.awaitTermination(3, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }

        // Verify that both tasks have completed successfully
        assertEquals(true, future1.isDone());
        assertEquals(true, future2.isDone());

        // Shutdown the thread pool to release resources
        executor.shutdown();
    }
}
```

This test creates a thread pool with 2 threads and submits two tasks to it. The first task sleeps for 1000 milliseconds (1 second) and prints "Task 1 completed". The second task sleeps for 2000 milliseconds (2 seconds) and prints "Task 2 completed".

The test then waits for the tasks to complete by calling `executor.awaitTermination(3, TimeUnit.SECONDS)`. This method blocks until all submitted tasks have completed or an optional timeout is reached.

Finally, the test verifies that both tasks have completed successfully using the `isDone()` method. If either task has not completed, this assertion will fail.

