Here's an example of implementing Breadth-First Search (BFS) algorithm in TypeScript:

```typescript
interface Node {
  value: any;
  children: Node[];
}

function bfs(rootNode: Node, targetValue: any): Node | null {
  if (!rootNode) return null;

  const queue = [{ node: rootNode, visited: false }];
  let currentTarget = null;

  while (queue.length > 0) {
    const { node, visited } = queue.shift();

    if (visited) {
      // If we've reached the target value, stop searching
      if (node.value === targetValue) return node;
    }

    for (const child of node.children) {
      if (!child.visited) {
        child.visited = true; // Mark as visited to avoid revisiting

        queue.push({ node: child, visited: false });
      }
    }
  }

  return currentTarget;
}
```

