using System;

public class MergeSort
{
    public static void Sort(int[] arr)
    {
        int left = 0;
        int right = arr.Length - 1;

        while (right > left)
        {
            // Base case: If the array has only one element, it's already sorted.
            if (arr.Length == 1)
                break;

            int mid = (left + right) / 2; // Calculate middle index

            // Recursively sort two halves of the array
            Sort(arr, left, mid);
            Sort(arr, mid + 1, right);

            // Merge sorted halves into a single array
            for (int i = left; i <= right; i++)
                arr[i] = Merge(arr, left, mid, mid + 1, right);
        }
    }

    private static int[] Merge(int[] arr, int l, int r, int m, int n)
    {
        // Create a new array to store the merged result
        int[] res = new int[r - l + 1];

        for (int i = 0; i <= m; i++)
            res[i] = arr[l + i];

        for (int i = 0; i < n - m; i++)
            arr[l + r + i] = arr[m + 1 + i];

        return res;
    }
}
