public class LRUCache {
    private int capacity; // Maximum number of items that can be stored
    private Map<String, String> cacheMap; // Key-value pair storage

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.cacheMap = new HashMap<>();
    }

    public void put(String key, String value) {
        if (cacheMap.size() >= capacity) { // Check if the cache is full
            String leastRecentlyUsedKey = getLeastRecentlyUsedKey(); // Find the LRU item to remove
            cacheMap.remove(leastRecentlyUsedKey); // Remove the LRU item from the cache
        }
        cacheMap.put(key, value); // Add or update the new item in the cache
    }

    public String get(String key) {
        return cacheMap.get(key);
    }

    private String getLeastRecentlyUsedKey() { // Helper method to find the LRU key
        long leastTimeUsed = Long.MAX_VALUE;
        String lruKey = null;
        for (Map.Entry<String, String> entry : cacheMap.entrySet()) {
            if (entry.getValue().lastAccessed < leastTimeUsed) {
                leastTimeUsed = entry.getValue().lastAccessed;
                lruKey = entry.getKey();
            }
        }
        return lruKey;
    }

    private static class CacheItem { // Inner class to store the cache item's last access time
        public long lastAccessed; // Last accessed timestamp

        public CacheItem(long lastAccessed) {
            this.lastAccessed = lastAccessed;
        }
    }
}
