type Graph = Record<string, Array<Node>>;

function dijkstra(graph: Graph, startNode: string) {
  const nodes = new Map();
  let minHeap = [{ node: startNode, distance: 0 }];

  while (minHeap.length > 0) {
    const { node, distance } = minHeap.shift();

    if (!nodes.has(node)) {
      nodes.set(node, { distance, visited: false });

      // Explore neighbors
      graph[node].forEach((neighbor: Node) => {
        if (!neighbor.visited && neighbor.distance < (nodes.get(neighbor.node)?.distance || Infinity)) {
          const newDistance = Math.min(distance + 1, neighbor.distance);
          minHeap.push({ node: neighbor.node, distance: newDistance });
          nodes.set(neighbor.node, { ...neighbor, visited: true });
        }
      });
    } else {
      // If the node is already visited and its distance is not updated, skip it
      if (nodes.get(node)?.distance === distance) continue;

      // Update the node's distance and re-add to the heap
      nodes.set(node, { ...nodes.get(node), distance });
      minHeap.push({ node: node, distance: nodes.get(node).distance });
    }
  }

  return nodes.values();
}

