```java
public class MergeSort {
    public static void main(String[] args) {
        int[] arr = {5, 2, 7, 9, 4, 6};
        System.out.println("Original array: " + java.util.Arrays.toString(arr));

        mergeSort(arr);
        System.out.println("Sorted array: " + java.util.Arrays.toString(arr));
    }

    public static void mergeSort(int[] arr) {
        if (arr.length <= 1) {
            return; // base case
        }

        int mid = arr.length / 2;
        int leftHalf = 0;
        int rightHalf = mid;

        mergeSort(arr, 0, mid);
        mergeSort(arr, mid + 1, arr.length - 1);

        // merge the two halves
        for (int i = 0; i <= mid; i++) {
            System.arraycopy(arr, leftHalf + i, arr, rightHalf + i + 1, mid - leftHalf);
        }

        System.arraycopy(arr, 0, arr, 0, leftHalf + 1);
    }

    public static void merge(int[] arr, int left, int right) {
        int[] temp = new int[arr.length];
        int i = 0;
        int j = 0;

        while (i < left && j < right) {
            if (arr[i] <= arr[j]) {
                temp[i++] = arr[i++];
            } else {
                temp[i++] = arr[j++];
            }
        }

        System.arraycopy(arr, left, temp, i, right - left);
        System.arraycopy(arr, right, temp, i + (right - left), left);

        for (int k = 0; k < arr.length; k++) {
            arr[k] = temp[k];
        }
    }
}
```

