```typescript
class CircuitBreaker {
  private maxRetries: number;
  private retries: number;

  constructor(maxRetries: number) {
    this.maxRetries = maxRetries;
    this.retries = 0;
  }

  async tryOperation(operation: () => Promise<void>): Promise<void> {
    while (this.retries < this.maxRetries) {
      try {
        await operation();
        return; // Operation successful, no need to retry
      } catch (error) {
        if (error instanceof Error && error.message.includes("timeout")) {
          throw new Error(`Operation timed out. Retrying...`);
        }
        console.error(`Error occurred: ${error}`);
        this.retries++;
        if (this.retries >= this.maxRetries) {
          throw new Error(`Maximum retries exceeded: ${this.maxRetries}`);
        }
      }
    }

    // If we reach here, it means the operation failed after max retries
    throw new Error("Operation failed");
  }
}
```

