public class LRUCache<T>
{
    private Dictionary<string, T> _cache = new Dictionary<string, T>();
    private int _capacity;

    public LRUCache(int capacity)
    {
        _capacity = capacity;
    }

    public void Insert(string key, T value)
    {
        if (key == null || value == null)
            throw new ArgumentException("Key and value cannot be null.");

        // Move the item to the end of the cache
        _cache[key] = value;

        // If the cache exceeds its capacity, remove the least recently used item
        if (_cache.Count > _capacity)
        {
