import crypto = require('crypto');

// Function to encrypt data using AES-256
function aesEncrypt(data: string, key: string) {
  const algorithm = 'aes-256-cbc';
  const mode = 'ecb'; // ECB (Electronic Coincidence Circuit) is a simple substitution cipher that uses the same key for encryption and decryption.
  const padding = crypto.randomBytes(16); // Generate random bytes to pad the data

  let encryptedData: Buffer;
  try {
    const cipher = crypto.createCipher(algorithm, key, { mode });
    const paddedData = Buffer.concat([Buffer.from(data), padding]);
    encryptedData = cipher.update(paddedData);
    if (encryptedData.length === 0) {
      // If no data is left after encryption, remove the padding
      encryptedData = Buffer.from(encryptedData);
    }
  } catch (err) {
    console.error('Error encrypting data:', err);
    return null;
  }

  return encryptedData.toString();
}

// Function to decrypt data using AES-256
function aesDecrypt(data: string, key: string) {
  const algorithm = 'aes-256-cbc';
  const mode = 'ecb'; // ECB (Electronic Coincidence Circuit) is a simple substitution cipher that uses the same key for encryption and decryption.

  let decryptedData: Buffer;
  try {
    const decipher = crypto.createDecipher(algorithm, key, { mode });
    encryptedData = Buffer.from(data);
    decryptedData = decipher.update(encryptedData);
    if (decryptedData.length === 0) {
      // If no data is left after decryption, remove the padding
      decryptedData = Buffer.from(decryptedData);
    }
  } catch (err) {
    console.error('Error decrypting data:', err);
    return null;
  }

  return decryptedData.toString();
}

